    func settle(_ allowed: Bool) {
        lock.lock()
        let first = value == nil
        if first { value = allowed }
        lock.unlock()
        if first { semaphore.signal() }
    }

    func wait() -> Bool {
        semaphore.wait()
        lock.lock()
        defer { lock.unlock() }
        return value ?? false
    }
}

