316	    /// What the priced responses of a turn with an unknown one came to:
317	    /// ` · at least $%.4f`, or ` · the priced part under $0.0001` for a
318	    /// positive amount that would round to 0.
319	    static func pricedPart(_ dollars: Double) -> String {
320	        if dollars > 0 && dollars < 0.000_05 { return " · the priced part under $0.0001" }
321	        return " · at least " + String(format: "$%.4f", dollars)
322	    }
