324	    /// The `yyyy-MM-dd` of the ISO 8601 instant `asOf` in `zone`; its first 10
325	    /// characters when it does not parse.
326	    static func day(_ asOf: String, in zone: TimeZone = .current) -> String {
327	        guard let instant = AssistantSpend.instant(asOf) else { return String(asOf.prefix(10)) }
328	        let formatter = DateFormatter()
329	        formatter.locale = Locale(identifier: "en_US_POSIX")
330	        formatter.calendar = Calendar(identifier: .gregorian)
331	        formatter.timeZone = zone
332	        formatter.dateFormat = "yyyy-MM-dd"
333	        return formatter.string(from: instant)
