3	/// The window's one assistant session (spec §11 AI-4): opened on first ask,
4	/// replaced once it has closed (a dead helper), and closed with the window.
5	/// The stored `assistant`, `assistantTranscript` and `assistantView` are in
6	/// `EditorViewController.swift`. Road map 12 A1; A2 adds the Assistant tab's
7	/// glue: the view is handed over by the inspector (`installAssistant`), its
8	/// five intents come back here, and every change of phase or question is
9	/// pushed to it by `assistantRefresh()`, which runs last in each path that
10	/// can change either — `AssistantSession.send` switches to busy and emits
11	/// nothing, so no event would say so.
12	extension EditorViewController {
13	
14	    /// The live session, else a new one for this window's project. Main only.
15	    func assistantSession() -> Result<AssistantSession, AssistantOpenError> {
16	        if let live = assistant, live.phase != .closed { return .success(live) }
17	        guard let document else {
18	            return .failure(AssistantOpenError(message: "This window has no project."))
19	        }
20	        switch AssistantSession.open(document: document) {
21	        case .failure(let error):
22	            return .failure(error)
23	        case .success(let session):
24	            assistant = session
25	            session.onEvent = assistantEventHandler(spendFolder: AssistantSpend.folder())
26	            if let window = view.window {
27	                let center = NotificationCenter.default
28	                center.removeObserver(self, name: NSWindow.willCloseNotification, object: window)
29	                center.addObserver(
30	                    self, selector: #selector(assistantWindowWillClose(_:)),
31	                    name: NSWindow.willCloseNotification, object: window)
32	            }
33	            return .success(session)
34	        }
35	    }
36	
37	    /// Each session event: into the transcript, and a `cost` into the spend
38	    /// ledger in `spendFolder`, resolved once for the session (spec §11 P-5).
39	    /// A ledger that cannot be written is one transcript note per session.
40	    private func assistantEventHandler(spendFolder: URL?) -> ([String: Any]) -> Void {
41	        var ledgerFailed = false
42	        return { [weak self] event in
43	            self?.assistantTranscript.take(event)
44	            if let failure = AssistantSpend.record(event, in: spendFolder), !ledgerFailed {
45	                ledgerFailed = true
46	                self?.assistantTranscript.note(failure)
47	            }
48	            self?.assistantRefresh()
49	        }
50	    }
51	
52	    /// Closing the window ends its conversation: a pending question is
53	    /// declined (AI-7) and the helper's stdin is closed.
54	    @objc func assistantWindowWillClose(_ note: Notification) {
55	        assistant?.close()
56	        assistant = nil
57	    }
58	
59	    // MARK: - The Assistant tab
60	
61	    /// From `installInspector`: the view arrives when the tab is first shown,
62	    /// and a key or model change from Settings reaches this window.
63	    func installAssistant(on inspector: InspectorViewController) {
64	        inspector.onAssistantView = { [weak self] view in self?.attachAssistant(view) }
65	        NotificationCenter.default.addObserver(
66	            self, selector: #selector(assistantConfigurationDidChange(_:)),
67	            name: AssistantConfiguration.didChangeNotification, object: nil)
68	    }
69	
70	    /// Hosts the conversation in `view`: the tab today, a floating window
71	    /// later (AI-4).
72	    func attachAssistant(_ view: AssistantView) {
73	        assistantView = view
74	        view.onSend = { [weak self] text in self?.assistantSend(text) ?? false }
75	        view.onStop = { [weak self] in self?.assistantStop() }
76	        view.onAnswer = { [weak self] allowed in self?.assistantAnswer(allowed) }
77	        view.onClear = { [weak self] in self?.assistantClear() }
78	        view.onOpenSettings = {
79	            NSApp.sendAction(#selector(AppDelegate.showSettings(_:)), to: nil, from: nil)
80	        }
