3	/// What the UTC calendar month has cost, for Settings ▸ Assistant (road map
4	/// 13 P4, spec §11 P-4, P-7): the month an instant falls in, its title, the
5	/// fold of `spend.jsonl` over it, the off-main read, and the sentences the
6	/// pane shows.
7	///
8	/// **The month is UTC's.** The ledger's `time` is written in UTC
9	/// (`AssistantSpend.ledgerLine`) and P-6's budget month is UTC, so the app
10	/// and the proofs count one month; the title says "(UTC)". `zone` is the one
11	/// spelling of that zone in this file.
12	///
13	/// **The fold only sums.** It adds the dollars the helper computed and
14	/// counts what it could not: a line without a price is `unpriced`, never
15	/// $0 (P-2), and a line that is not a JSON object with a readable `time` is
16	/// `unreadable`. Lines of another `service` are skipped. No pricing
17	/// arithmetic is done here (road map 13 §2).
18	///
19	/// **The read is off main.** `read` folds on `queue`, one serial queue, and
20	/// answers on main; the pane shows only its latest read's answer.
21	enum AssistantSpendMonth {
22	    static let queue = DispatchQueue(label: "com.kgalligan.framejob.spend-month")
23	    static let zone = TimeZone.gmt
24	    static let note =
25	        "Frame Job's own estimate at LiteLLM prices, from its spend ledger. The Anthropic "
26	        + "Console shows what your account was billed."
27	
28	    /// One month's lines, folded.
29	    struct Summary: Equatable {
30	        var dollars = 0.0
31	        var priced = 0
32	        var unpriced = 0
33	        var unreadable = 0
34	    }
35	
36	    /// What the pane has to say: no ledger kept, a read under way, a
37	    /// month's summary, or a read that failed (its reason).
38	    enum Reading: Equatable {
39	        case noLedger, reading
40	        case summary(Summary)
41	        case failed(String)
42	    }
43	
44	    /// The gregorian calendar month holding `instant`, in `zone`.
45	    static func month(containing instant: Date) -> DateInterval {
46	        var calendar = Calendar(identifier: .gregorian)
47	        calendar.timeZone = zone
48	        return calendar.dateInterval(of: .month, for: instant)
49	            ?? DateInterval(start: instant, duration: 0)
50	    }
51	
52	    /// "September 2026 (UTC)".
53	    static func title(_ month: DateInterval) -> String {
54	        let formatter = DateFormatter()
55	        formatter.locale = Locale(identifier: "en_US_POSIX")
56	        formatter.calendar = Calendar(identifier: .gregorian)
57	        formatter.timeZone = zone
58	        formatter.dateFormat = "LLLL yyyy"
59	        return formatter.string(from: month.start) + " (UTC)"
60	    }
61	
62	    /// The ledger's lines in `month`, folded. Pure.
63	    static func fold(_ data: Data, month: DateInterval) -> Summary {
64	        var summary = Summary()
65	        let text = String(decoding: data, as: UTF8.self)
66	        for line in text.split(separator: "\n", omittingEmptySubsequences: false) {
67	            guard !line.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else { continue }
68	            guard
69	                let object = try? JSONSerialization.jsonObject(with: Data(line.utf8)),
70	                let entry = object as? [String: Any],
71	                let time = entry["time"] as? String,
72	                let instant = AssistantSpend.instant(time)
73	            else {
74	                summary.unreadable += 1
75	                continue
76	            }
77	            guard entry["service"] as? String == "anthropic" else { continue }
78	            guard month.start <= instant && instant < month.end else { continue }
79	            if let dollars = AssistantSpend.number(entry["dollars"])?.doubleValue,
80	                dollars.isFinite, dollars >= 0
81	            {
82	                summary.priced += 1
83	                summary.dollars += dollars
84	            } else {
85	                summary.unpriced += 1
86	            }
87	        }
88	        return summary
89	    }
90	
91	    /// Reads and folds `ledger` on `queue`; `completion` runs on main.
92	    static func read(
93	        ledger: URL, month: DateInterval, completion: @escaping (Reading) -> Void
94	    ) {
95	        queue.async {
96	            let reading: Reading
97	            do {
98	                reading = .summary(fold(try Data(contentsOf: ledger), month: month))
99	            } catch {
100	                reading = .failed(error.localizedDescription)
101	            }
102	            DispatchQueue.main.async { completion(reading) }
103	        }
104	    }
105	
106	    /// `$%.2f`, or `under $0.01` for a positive amount that would round to 0.
107	    static func amount(_ dollars: Double) -> String {
108	        if dollars > 0 && dollars < 0.005 { return "under $0.01" }
109	        return String(format: "$%.2f", dollars)
110	    }
111	
112	    /// What Settings says for `reading` over `month`.
113	    static func sentence(_ reading: Reading, month: DateInterval) -> String {
114	        switch reading {
115	        case .noLedger:
116	            return "This launch keeps no spend ledger."
117	        case .reading:
118	            return "Reading the spend ledger…"
119	        case .failed(let reason):
120	            let bare = reason.hasSuffix(".") ? String(reason.dropLast()) : reason
121	            return "The spend ledger could not be read: \(bare)."
122	        case .summary(let summary):
123	            let title = title(month)
124	            let count = summary.priced + summary.unpriced
125	            let responses = "\(count) " + (count == 1 ? "response" : "responses")
126	            var text: String
127	            if count == 0 {
128	                text = "Nothing recorded in \(title)."
129	            } else if summary.unpriced == 0 {
130	                text = "\(title): \(amount(summary.dollars)) over \(responses)."
131	            } else if summary.priced == 0 {
132	                text = "\(title): \(responses); none could be priced."
133	            } else {
134	                text =
135	                    "\(title): \(responses); \(summary.unpriced) could not be priced, the rest "
136	                    + "came to \(amount(summary.dollars))."
137	            }
138	            if summary.unreadable > 0 {
139	                let lines = summary.unreadable == 1 ? "line" : "lines"
140	                text += " \(summary.unreadable) ledger \(lines) could not be read."
141	            }
142	            return text
143	        }
144	    }
145	}
