import Foundation

/// One line of the Assistant tab's transcript: what the person sent, the
/// assistant's streamed reply, its progress notes between tool calls, a meta
/// line (a tool call, a failed result, an answer, compaction, a note the app
/// writes), or an error.
struct AssistantEntry: Equatable {
    enum Kind: String {
        case person, reply, progress, meta, error
    }

    let kind: Kind
    var text: String
}

/// What changed in the transcript, so a view redraws one entry rather than
/// all of them. `extended` carries the entry's WHOLE text now.
enum AssistantTranscriptChange: Equatable {
    case appended(AssistantEntry)
    case extended(index: Int, text: String)
    case cleared
    case usage(AssistantContextUsage)
    /// The conversation's cost so far (road map 13 P4, spec §11 P-7).
    case conversationCost(AssistantTurnCost)
}

/// The window's conversation as the person reads it (road map 12 A2): the
/// session's events turned into entries, and the context usage the helper
/// last reported. Rasterize's `AssistantPanelViewController.handleEvent`,
/// ported as storage with no views, so the tab and a later floating window
/// (spec §11 AI-4) draw the same transcript. It lives on
/// `EditorViewController.assistantTranscript`, beside the session; the view
/// holds none of it. Main only.
final class AssistantTranscript {
    private(set) var entries: [AssistantEntry] = []
    private(set) var usage = AssistantContextUsage()
    /// Every `cost` event since the last Clear or ended conversation, summed:
    /// the tab's Spend row (spec §11 P-7). In memory, so it carries across a
    /// helper restart and needs no spend folder.
    private(set) var conversationCost = AssistantTurnCost()

    /// Each change, as it happens.
    var onChange: ((AssistantTranscriptChange) -> Void)?

    /// The delta type ("text_delta" / "progress_delta") extending the newest
    /// entry; any other event, or a line the app writes, ends it.
    private var streamingType: String?
    /// The last question's sentence, which the answer event does not carry.
    private var questionSentence = ""
    /// The running turn's `cost` events, summed (road map 13 P2).
    private var turnCost = AssistantTurnCost()

    /// What the person sent.
    func person(_ text: String) {
        streamingType = nil
        append(.person, text)
    }

    /// A meta line the app writes (a settings change, say).
    func note(_ text: String) {
        streamingType = nil
        append(.meta, text)
    }

    /// One `AssistantSession` event.
    func take(_ event: [String: Any]) {
        let type = event["type"] as? String
        if type != streamingType { streamingType = nil }
        switch type {
        case "text_delta":
            delta(event["text"] as? String ?? "", type: "text_delta", kind: .reply)
        case "progress_delta":
            delta(event["text"] as? String ?? "", type: "progress_delta", kind: .progress)
        case "compaction_started":
            let used = (event["used"] as? Int ?? 0).formatted()
            append(.meta, "Compacting the conversation (\(used) tokens)…")
        case "compacted":
            let before = (event["before"] as? Int ?? 0).formatted()
            let after = (event["after"] as? Int ?? 0).formatted()
            append(
                .meta,
                "Compacted: \(before) → about \(after) tokens. Earlier renders are gone; "
                    + "the assistant re-renders when it needs to look.")
        case "compaction_failed":
            let reason = event["reason"] as? String ?? "no summary came back"
            append(
                .meta,
                "Compaction didn't finish (\(reason)); it will try again after the next turn.")
        case "tool_results_cleared":
            let uses = event["tool_uses"] as? Int ?? 0
            let tokens = (event["tokens"] as? Int ?? 0).formatted()
            append(
                .meta, "Cleared \(uses) old tool results (\(tokens) tokens) from the model's view.")
        case "context_usage":
            setUsage(
                AssistantContextUsage(
                    used: event["used"] as? Int ?? 0, limit: event["limit"] as? Int,
                    reported: true))
        case "tool_call":
            let name = event["name"] as? String ?? "?"
            append(.meta, name + Self.argumentSummary(event["arguments"]))
        case "tool_result":
            if event["is_error"] as? Bool == true {
                append(.meta, "failed: \(event["summary"] as? String ?? "")")
            }
        case "question":
            questionSentence = event["sentence"] as? String ?? ""
        case "answer":
            let by = event["by"] as? String ?? "person"
            if event["allowed"] as? Bool == true {
                append(.meta, "Allowed: \(questionSentence)")
            } else if by == "person" {
                append(.meta, "Declined: \(questionSentence)")
            } else {
                append(.meta, "Declined (\(by)): \(questionSentence)")
            }
        case "error":
            append(.error, event["message"] as? String ?? "Unknown error.")
        case "turn_started":
            turnCost = AssistantTurnCost()
        case "cost":
            turnCost.add(event)
            conversationCost.add(event)
            onChange?(.conversationCost(conversationCost))
        case "turn_finished":
            if let line = turnCost.line { append(.meta, line) }
            turnCost = AssistantTurnCost()
        default:
            break
        }
    }

    /// Clear: every entry gone, the cost and the usage back to none. The
    /// window size is the model's, so it is kept.
    func clear() {
        entries = []
        streamingType = nil
        questionSentence = ""
        turnCost = AssistantTurnCost()
        onChange?(.cleared)
        resetConversationCost()
        setUsage(AssistantContextUsage(used: 0, limit: usage.limit, reported: usage.reported))
    }

    /// The conversation ended under the transcript (a key or model change):
    /// the note says so, and the cost and the usage start over.
    func endConversation(note text: String) {
        note(text)
        turnCost = AssistantTurnCost()
        resetConversationCost()
        setUsage(AssistantContextUsage(used: 0, limit: usage.limit, reported: usage.reported))
    }

    /// " (k: v, …)" for a tool call's arguments, sorted, `project` dropped,
    /// the first 70 characters; "" when there is nothing to show.
    static func argumentSummary(_ arguments: Any?) -> String {
        guard let arguments = arguments as? [String: Any], !arguments.isEmpty else { return "" }
        let parts = arguments
            .filter { $0.key != "project" }
            .map { "\($0.key): \(compact($0.value))" }
            .sorted()
            .joined(separator: ", ")
        guard !parts.isEmpty else { return "" }
        return " (\(String(parts.prefix(70))))"
    }

    /// A string as itself; anything else as one line of JSON, so an id array
    /// reads `[3,4]` and a boolean `true`.
    private static func compact(_ value: Any) -> String {
        if let string = value as? String { return string }
        guard
            JSONSerialization.isValidJSONObject([value]),
            let data = try? JSONSerialization.data(
                withJSONObject: value, options: [.fragmentsAllowed, .sortedKeys]),
            let text = String(data: data, encoding: .utf8)
        else { return "\(value)" }
        return text
    }

    // MARK: - Private

    private func append(_ kind: AssistantEntry.Kind, _ text: String) {
        let entry = AssistantEntry(kind: kind, text: text)
        entries.append(entry)
        onChange?(.appended(entry))
    }

    /// Streams into the newest entry while the same delta type runs; the
    /// first delta of a run opens an entry.
    private func delta(_ text: String, type: String, kind: AssistantEntry.Kind) {
        guard streamingType == type, let last = entries.indices.last else {
            append(kind, text)
            streamingType = type
            return
        }
        entries[last].text += text
        onChange?(.extended(index: last, text: entries[last].text))
    }

    private func resetConversationCost() {
        conversationCost = AssistantTurnCost()
        onChange?(.conversationCost(conversationCost))
    }

    private func setUsage(_ next: AssistantContextUsage) {
        usage = next
        onChange?(.usage(next))
    }
}

1	// What one Messages API response cost, from its own `usage` and `model` and a
2	// price table of LiteLLM's Anthropic rows in US dollars per million tokens
3	// (prices/anthropic.json). Pure: no I/O, and `price` never throws and never
4	// answers NaN, whatever JSON value `usage` is. A model the table does not
5	// hold, and usage the table cannot price (fast mode, a batch or priority
6	// tier, a US-only request, a malformed count, a class whose rate the row
7	// lacks), answers `unknown` with its cause, never $0.
8	//
9	// When `usage.iterations` is a non-empty array, each element is priced at
10	// its own `model` (or the response's), because the top-level counts describe
11	// only the attempt that returned the message and leave out compaction and a
12	// refused attempt before a fallback.
13	
14	export type Rates = {
15	  input?: number;
16	  output?: number;
17	  cache_read?: number;
18	  cache_write_5m?: number;
19	  cache_write_1h?: number;
20	};
21	export type PriceRow = Rates & { above_200k?: Rates };
22	export type PriceTable = {
23	  format: 1;
24	  provider: "anthropic";
25	  unit: "USD per million tokens";
26	  source: string;
27	  litellm_commit?: string;
28	  litellm_commit_date?: string;
29	  fetched_at?: string;
30	  models: Record<string, PriceRow>;
31	};
32	export type UnknownCause = "model" | "rate" | "usage" | "speed" | "service_tier" | "inference_geo";
33	export type Price =
34	  | { kind: "dollars"; dollars: number; rows: string[] }
35	  | { kind: "unknown"; cause: UnknownCause; detail: string };
36	
37	type JsonObject = { [key: string]: unknown };
38	type Counts = { input: number; write5m: number; write1h: number; read: number; output: number; total: number };
39	type Entry = { value: JsonObject; model: string };
40	type CountKey = "input" | "write5m" | "write1h" | "read" | "output";
41	
42	const TIER_THRESHOLD = 200_000;
43	const DATED = /-[0-9]{8}$/;
44	/** The order a class's cost is added in; the Python reader uses the same. */
45	const CLASSES: ReadonlyArray<[keyof Rates, CountKey]> = [
46	  ["input", "input"],
47	  ["cache_write_5m", "write5m"],
48	  ["cache_write_1h", "write1h"],
49	  ["cache_read", "read"],
50	  ["output", "output"],
51	];
52	
53	function isObject(value: unknown): value is JsonObject {
54	  return value !== null && typeof value === "object" && !Array.isArray(value);
55	}
56	
57	function own(object: object, key: string): boolean {
58	  return Object.prototype.hasOwnProperty.call(object, key);
59	}
60	
61	function unknown(cause: UnknownCause, detail: string): Price {
62	  return { kind: "unknown", cause, detail };
63	}
64	
65	/** The table key a response's model id prices at: the exact id, or the id
66	 *  less a trailing `-YYYYMMDD` when that is a key; nothing else is stripped. */
67	export function matchModel(model: string, table: PriceTable): string | null {
68	  const models = table.models;
69	  if (own(models, model)) return model;
70	  if (DATED.test(model)) {
71	    const bare = model.slice(0, -9);
72	    if (own(models, bare)) return bare;
73	  }
74	  return null;
75	}
76	
77	/** A count: absent or null is 0, else a non-negative integer, else null. */
78	function count(object: JsonObject, key: string): number | null {
79	  const value = object[key];
80	  if (value === undefined || value === null) return 0;
81	  if (typeof value !== "number" || !Number.isInteger(value) || value < 0) return null;
82	  return value;
83	}
84	
85	function counts(entry: JsonObject): Counts | string {
86	  const input = count(entry, "input_tokens");
87	  const creation = count(entry, "cache_creation_input_tokens");
88	  const read = count(entry, "cache_read_input_tokens");
89	  const output = count(entry, "output_tokens");
90	  if (input === null) return "input_tokens is not a non-negative integer";
91	  if (creation === null) return "cache_creation_input_tokens is not a non-negative integer";
92	  if (read === null) return "cache_read_input_tokens is not a non-negative integer";
93	  if (output === null) return "output_tokens is not a non-negative integer";
94	  let write5m = creation;
95	  let write1h = 0;
96	  const split = entry["cache_creation"];
97	  if (isObject(split)) {
98	    const five = count(split, "ephemeral_5m_input_tokens");
99	    const hour = count(split, "ephemeral_1h_input_tokens");
100	    if (five === null) return "cache_creation.ephemeral_5m_input_tokens is not a non-negative integer";
101	    if (hour === null) return "cache_creation.ephemeral_1h_input_tokens is not a non-negative integer";
102	    write5m = five;
103	    write1h = hour;
104	  }
105	  return { input, write5m, write1h, read, output, total: input + creation + read };
106	}
107	
108	function usable(rate: unknown): rate is number {
109	  return typeof rate === "number" && Number.isFinite(rate) && rate >= 0;
110	}
111	
112	function allowed(usage: JsonObject, key: string, ok: string): boolean {
113	  const value = usage[key];
114	  return value === undefined || value === null || value === ok;
115	}
116	
117	export function price(usage: unknown, model: string, table: PriceTable): Price {
118	  // 1. The shapes.
119	  if (!isObject(usage)) return unknown("usage", "usage is not an object");
120	  if (typeof model !== "string" || model === "") return unknown("model", "no model id");
121	
122	  // 2. Modes the table has no rate for.
123	  if (!allowed(usage, "speed", "standard")) {
124	    return unknown("speed", `speed ${JSON.stringify(usage["speed"])} is not priced`);
125	  }
126	  if (!allowed(usage, "service_tier", "standard")) {
127	    return unknown("service_tier", `service_tier ${JSON.stringify(usage["service_tier"])} is not priced`);
128	  }
129	  if (!allowed(usage, "inference_geo", "global")) {
130	    return unknown("inference_geo", `inference_geo ${JSON.stringify(usage["inference_geo"])} is not priced`);
131	  }
132	
133	  // 3. The entries.
134	  const entries: Entry[] = [];
135	  const iterations = usage["iterations"];
136	  if (iterations !== undefined && iterations !== null && !Array.isArray(iterations)) {
137	    return unknown("usage", "iterations is not an array");
138	  }
139	  if (Array.isArray(iterations) && iterations.length > 0) {
140	    for (let i = 0; i < iterations.length; i++) {
141	      const element: unknown = iterations[i];
142	      if (!isObject(element)) return unknown("usage", `iterations[${i}] is not an object`);
143	      const named = element["model"];
144	      entries.push({ value: element, model: typeof named === "string" && named !== "" ? named : model });
145	    }
146	  } else {
147	    entries.push({ value: usage, model });
148	  }
149	
150	  // 4. The counts.
151	  const tallies: Counts[] = [];
152	  for (let i = 0; i < entries.length; i++) {
153	    const answer = counts(entries[i].value);
154	    if (typeof answer === "string") return unknown("usage", entries.length > 1 ? `iterations[${i}].${answer}` : answer);
155	    tallies.push(answer);
156	  }
157	
158	  // 5. The rows.
159	  const keys: string[] = [];
160	  for (const entry of entries) {
161	    const key = matchModel(entry.model, table);
162	    if (key === null) return unknown("model", `${entry.model} is not in the price table`);
163	    keys.push(key);
164	  }
165	
166	  // 6. The tier and the rates.
167	  const rates: Rates[] = [];
168	  for (let i = 0; i < entries.length; i++) {
169	    const row: unknown = table.models[keys[i]];
170	    if (!isObject(row)) return unknown("rate", `${keys[i]} has no rates`);
171	    const above = row["above_200k"];
172	    const tiered = isObject(above) && tallies[i].total > TIER_THRESHOLD;
173	    const chosen: Rates = (tiered ? above : row) as Rates;
174	    for (const [rateKey, countKey] of CLASSES) {
175	      if (tallies[i][countKey] > 0 && !usable(chosen[rateKey])) {
176	        return unknown("rate", `${keys[i]} has no ${tiered ? "above_200k " : ""}${rateKey} rate`);
177	      }
178	    }
179	    rates.push(chosen);
180	  }
181	
182	  // 7. The arithmetic.
183	  let dollars = 0;
184	  for (let i = 0; i < entries.length; i++) {
185	    let s = 0;
186	    for (const [rateKey, countKey] of CLASSES) {
187	      const tokens = tallies[i][countKey];
188	      if (tokens === 0) continue;
189	      s += tokens * (rates[i][rateKey] as number);
190	    }
191	    dollars += s / 1_000_000;
192	  }
193	  const rows: string[] = [];
194	  for (const key of keys) if (!rows.includes(key)) rows.push(key);
195	  return { kind: "dollars", dollars, rows };
196	}
