1	// The price table in force (spec §11 P-1, P-5): the snapshot bundled into the
2	// helper (prices/anthropic.json), a cached copy of LiteLLM's table that the
3	// helper refreshes at most once a day, and the source it priced from, which
4	// is always reported so a stale table is never silent. The cache path comes
5	// from `configure`; without one the helper prices from the bundled table and
6	// fetches nothing. `reduceLiteLLM` is prices/update.py's `reduce_table`, step
7	// for step, with the feed and the fetch time in place of a LiteLLM commit.
8	
9	import { mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from "node:fs";
10	import { dirname, isAbsolute } from "node:path";
11	import bundled from "../prices/anthropic.json";
12	import type { PriceRow, PriceTable, Rates } from "./pricing";
13	import type { PriceSource } from "./protocol";
14	
15	export const LITELLM_URL = "https://raw.githubusercontent.com/BerriAI/litellm/main/model_prices_and_context_window.json";
16	export const REFRESH_AFTER_MS = 86_400_000, FETCH_TIMEOUT_MS = 30_000;
17	
18	export type LoadedPrices = { table: PriceTable; source: PriceSource };
19	export type PriceOptions = { cache?: string; feed?: string; now?: () => Date };
20	
21	type JsonObject = { [key: string]: unknown };
22	
23	const REQUIRED = ["claude-opus-5-5", "claude-fable-5-1"] as const;
24	const FIELDS: ReadonlyArray<[string, keyof Rates]> = [
25	  ["input_cost_per_token", "input"],
26	  ["output_cost_per_token", "output"],
27	  ["cache_read_input_token_cost", "cache_read"],
28	  ["cache_creation_input_token_cost", "cache_write_5m"],
29	  ["cache_creation_input_token_cost_above_1hr", "cache_write_1h"],
30	];
31	const BASE_KEYS = FIELDS.map(([, key]) => key);
32	const LOOPBACK = new Set(["127.0.0.1", "localhost", "[::1]"]);
33	
34	function isObject(value: unknown): value is JsonObject {
35	  return value !== null && typeof value === "object" && !Array.isArray(value);
36	}
37	
38	function own(object: object, key: string): boolean {
39	  return Object.prototype.hasOwnProperty.call(object, key);
40	}
41	
42	function isRate(value: unknown): value is number {
43	  return typeof value === "number" && Number.isFinite(value) && value >= 0;
44	}
45	
46	function message(error: unknown): string {
47	  return error instanceof Error ? error.message : String(error);
48	}
49	
50	/** Why `rates` is not a set of rates, or null. */
51	function ratesProblem(rates: JsonObject, where: string): string | null {
52	  for (const key of BASE_KEYS) {
53	    if (own(rates, key) && !isRate(rates[key])) return `${where} ${key} is not a finite non-negative number`;
54	  }
55	  return null;
56	}
57	
58	/** A `PriceTable` read from JSON, or why it is not one. */
59	export function parseTable(value: unknown): PriceTable | string {
60	  if (!isObject(value)) return "not a JSON object";
61	  if (value["format"] !== 1) return `format ${JSON.stringify(value["format"])}, not 1`;
62	  if (value["provider"] !== "anthropic") return `provider ${JSON.stringify(value["provider"])}`;
63	  if (value["unit"] !== "USD per million tokens") return `unit ${JSON.stringify(value["unit"])}`;
64	  if (typeof value["source"] !== "string") return "no source";
65	  for (const key of ["litellm_commit", "litellm_commit_date", "fetched_at"]) {
66	    if (own(value, key) && typeof value[key] !== "string") return `${key} is not a string`;
67	  }
68	  const models = value["models"];
69	  if (!isObject(models)) return "no models";
70	  for (const [model, row] of Object.entries(models)) {
71	    if (!isObject(row)) return `${model} is not a row`;
72	    const base = ratesProblem(row, model);
73	    if (base) return base;
74	    const above = row["above_200k"];
75	    if (above !== undefined) {
76	      if (!isObject(above)) return `${model} above_200k is not a row`;
77	      const tier = ratesProblem(above, `${model} above_200k`);
78	      if (tier) return tier;
79	    }
80	  }
81	  for (const model of REQUIRED) {
82	    const row = models[model];
83	    if (!isObject(row)) return `no ${model} row`;
84	    const missing = BASE_KEYS.filter((key) => !own(row, key));
85	    if (missing.length > 0) return `${model} lacks ${missing.join(", ")}`;
86	  }
87	  return value as unknown as PriceTable;
88	}
89	
90	/** update.py's `per_million`: dollars per token to dollars per million, to 6 places. */
91	function perMillion(value: unknown, model: string, field: string): number | string {
92	  if (!isRate(value)) return `${model}.${field} is not a finite non-negative number: ${JSON.stringify(value)}`;
93	  return Number((value * 1_000_000).toFixed(6));
94	}
95	
96	/** update.py's `reduce_row`. */
97	function reduceRow(model: string, entry: JsonObject): PriceRow | string {
98	  const row: PriceRow = {};
99	  const above: Rates = {};
100	  for (const [field, key] of FIELDS) {
101	    if (own(entry, field)) {
102	      const rate = perMillion(entry[field], model, field);
103	      if (typeof rate === "string") return rate;
104	      row[key] = rate;
105	    }
106	    const tier = field + "_above_200k_tokens";
107	    if (own(entry, tier)) {
108	      const rate = perMillion(entry[tier], model, tier);
109	      if (typeof rate === "string") return rate;
110	      above[key] = rate;
111	    }
112	  }
113	  if (Object.keys(above).length > 0) row.above_200k = above;
114	  return row;
115	}
116	
117	/** update.py's `reduce_table`: LiteLLM's anthropic rows, or why the document is refused. */
118	export function reduceLiteLLM(data: unknown, source: string, fetchedAt: string): PriceTable | string {
119	  if (!isObject(data)) return "the document is not a JSON object";
120	  const models: Record<string, PriceRow> = {};
121	  for (const [model, entry] of Object.entries(data)) {
122	    if (isObject(entry) && entry["litellm_provider"] === "anthropic") {
123	      const row = reduceRow(model, entry);
124	      if (typeof row === "string") return row;
125	      models[model] = row;
126	    }
127	  }
128	  if (Object.keys(models).length === 0) return 'no entry\'s litellm_provider is "anthropic"';
129	  for (const model of REQUIRED) {
130	    const row = models[model];
131	    if (row === undefined) return `no ${model} row`;
132	    const missing = BASE_KEYS.filter((key) => !own(row, key));
133	    if (missing.length > 0) return `${model} lacks ${missing.join(", ")}`;
134	  }
135	  return {
136	    format: 1,
137	    provider: "anthropic",
138	    unit: "USD per million tokens",
139	    source,
140	    fetched_at: fetchedAt,
141	    models,
142	  };
143	}
144	
145	/** Why the helper will not fetch `url`, or null: https, or http to a loopback host. */
146	export function feedProblem(url: string): string | null {
147	  let parsed: URL;
148	  try {
149	    parsed = new URL(url);
150	  } catch {
151	    return `the price feed ${url} is neither https nor a loopback http URL`;
152	  }
153	  if (parsed.protocol === "https:") return null;
154	  if (parsed.protocol === "http:" && LOOPBACK.has(parsed.hostname)) return null;
155	  return `the price feed ${url} is neither https nor a loopback http URL`;
156	}
157	
158	/** The table bundled into the helper, as of its LiteLLM commit's date. */
159	export function bundledPrices(): LoadedPrices {
160	  const table = parseTable(bundled as unknown);
161	  if (typeof table === "string") throw new Error(`the bundled price table is invalid: ${table}`);
162	  return { table, source: { kind: "bundled", as_of: table.litellm_commit_date ?? "" } };
163	}
164	
165	function withProblem(prices: LoadedPrices, problem: string): LoadedPrices {
166	  return { table: prices.table, source: { ...prices.source, problem } };
167	}
168	
169	/** The prices in force at `configure`, from the cache (read synchronously)
170	 *  or the bundled table, and whether a refresh is due. */
171	export function initialPrices(o: PriceOptions): { prices: LoadedPrices; refreshDue: boolean } {
172	  const now = (o.now ?? (() => new Date()))();
173	  const fallback = bundledPrices();
174	  if (!o.cache) return { prices: withProblem(fallback, "no price cache is configured"), refreshDue: false };
175	  if (!isAbsolute(o.cache)) {
176	    return { prices: withProblem(fallback, "the price cache path is not absolute"), refreshDue: false };
177	  }
178	  let text: string;
179	  try {
180	    text = readFileSync(o.cache, "utf8");
181	  } catch (error) {
182	    if ((error as { code?: string }).code === "ENOENT") return { prices: fallback, refreshDue: true };
183	    return { prices: withProblem(fallback, `the price cache is unreadable: ${message(error)}`), refreshDue: true };
184	  }
185	  let table: PriceTable | string;
186	  try {
187	    table = parseTable(JSON.parse(text));
188	  } catch (error) {
189	    table = `not JSON: ${message(error)}`;
190	  }
191	  if (typeof table === "string") {
192	    return { prices: withProblem(fallback, `the price cache is unreadable: ${table}`), refreshDue: true };
193	  }
194	  const fetchedAt = table.fetched_at ?? "";
195	  const at = Date.parse(fetchedAt);
196	  const age = now.getTime() - at;
197	  const refreshDue = Number.isNaN(at) || age >= REFRESH_AFTER_MS || age < 0;
198	  return { prices: { table, source: { kind: "cached", as_of: fetchedAt } }, refreshDue };
199	}
200	
201	/** A fresh table from the feed, written to the cache as the last step; on any
202	 *  failure, `current` with the problem and nothing written. Never rejects. */
203	export async function refreshPrices(current: LoadedPrices, o: PriceOptions): Promise<LoadedPrices> {
204	  try {
205	    if (!o.cache) return withProblem(current, "no price cache is configured");
206	    if (!isAbsolute(o.cache)) return withProblem(current, "the price cache path is not absolute");
207	    const feed = o.feed ?? LITELLM_URL;
208	    const refused = feedProblem(feed);
209	    if (refused) return withProblem(current, refused);
210	    let data: unknown;
211	    try {
212	      const response = await fetch(feed, {
213	        headers: { "user-agent": "framejob-agent" },
214	        signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
215	      });
216	      if (!response.ok) return withProblem(current, `fetching ${feed}: HTTP ${response.status}`);
217	      const body = await response.text();
218	      try {
219	        data = JSON.parse(body);
220	      } catch (error) {
221	        return withProblem(current, `${feed} was rejected: not JSON: ${message(error)}`);
222	      }
223	    } catch (error) {
224	      return withProblem(current, `fetching ${feed}: ${message(error)}`);
225	    }
226	    const fetchedAt = (o.now ?? (() => new Date()))().toISOString();
227	    const table = reduceLiteLLM(data, feed, fetchedAt);
228	    if (typeof table === "string") return withProblem(current, `${feed} was rejected: ${table}`);
229	    const fetched: LoadedPrices = { table, source: { kind: "fetched", as_of: fetchedAt } };
230	    const temporary = `${o.cache}.tmp-${process.pid}`;
231	    try {
232	      mkdirSync(dirname(o.cache), { recursive: true, mode: 0o700 });
233	      writeFileSync(temporary, JSON.stringify(table, null, 2) + "\n");
234	      renameSync(temporary, o.cache);
235	    } catch (error) {
236	      try {
237	        unlinkSync(temporary);
238	      } catch {
239	        // nothing was left behind
240	      }
241	      return withProblem(fetched, `the price cache could not be written: ${message(error)}`);
242	    }
243	    return fetched;
244	  } catch (error) {
245	    return withProblem(current, `fetching ${o.feed ?? LITELLM_URL}: ${message(error)}`);
246	  }
247	}
