    override func updateTrackingAreas() {
        super.updateTrackingAreas()
        // Owner-filtered — the pitfall is in `Controls.swift`'s
        // `StickerButton.updateTrackingAreas`. This control's tooltip is the
        // Media tab's "what Consolidate… does", among others.
        for area in trackingAreas where area.owner === self { removeTrackingArea(area) }
        addTrackingArea(
            NSTrackingArea(
                rect: bounds, options: [.mouseEnteredAndExited, .activeInKeyWindow],
                owner: self, userInfo: nil))
    }

    override func mouseEntered(with event: NSEvent) {
        hovered = true
        needsDisplay = true
    }

    override func mouseExited(with event: NSEvent) {
        hovered = false
        needsDisplay = true
    }

    override func mouseDown(with event: NSEvent) {
        guard isActive else { return }
        action()
        onEdit()
    }

    override func draw(_ dirtyRect: NSRect) {
        let path = NSBezierPath(
            roundedRect: bounds.insetBy(dx: 0.5, dy: 0.5),
            xRadius: DS.controlRadius, yRadius: DS.controlRadius)
        NSColor.controlBackgroundColor.setFill()
        path.fill()
        if hovered && isActive {
            DS.hoverFill.setFill()
            path.fill()
        }
        DS.border.setStroke()
        path.stroke()

        let attributes: [NSAttributedString.Key: Any] = [
            .font: DS.sans(11), .foregroundColor: DS.textStrong,
